<?php
declare(strict_types=1);
require __DIR__ . '/../src/Bootstrap.php';

use Sgsii\Http\ActionDispatcher;
use Sgsii\Http\Input;

set_exception_handler('handle_uncaught_exception');
$app = Bootstrap::createApplication(dirname(__DIR__));
$resources = Bootstrap::createResourceRepository($app);
$users = Bootstrap::createUserRepository($app);
$reservations = Bootstrap::createReservationRepository($app);
$dashboard = Bootstrap::createDashboardRepository($app);
$loans = Bootstrap::createLoanRepository($app);
$incidents = Bootstrap::createIncidentRepository($app);
$page = $_GET['page'] ?? (current_user() ? 'dashboard' : 'login');
$adminPages = ['users','rooms','supplies','loans','reports'];
if (in_array($page, $adminPages, true)) require_admin();
if ($page !== 'login') require_login();

/** Genera las opciones de salas e insumos para los selectores de recursos. */
function resource_options(array $rooms, array $supplies, ?string $selected = null): string { $html = ''; foreach ($rooms as $r) $html .= '<option value="room:' . $r['id'] . '"' . ($selected === 'room:' . $r['id'] ? ' selected' : '') . '>Sala - ' . e($r['name']) . '</option>'; foreach ($supplies as $s) $html .= '<option value="supply:' . $s['id'] . '"' . ($selected === 'supply:' . $s['id'] ? ' selected' : '') . '>Insumo - ' . e($s['name']) . '</option>'; return $html; }

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    try {
        ActionDispatcher::dispatch($app, $_POST, $loans, $reservations);
    } catch (Throwable $error) {
        if (!$error instanceof InvalidArgumentException) {
            log_internal_error($error);
        }
        flash('error', user_error_message($error));
        go($page);
    }
}

$flash = pull_flash(); $user = current_user();
$rooms = $resources->findActiveRooms();
$supplies = $resources->findActiveSupplies();
$nav = current_user() ? ['dashboard'=>'Inicio','availability'=>'Disponibilidad','reservations'=>'Reservas','incidents'=>'Incidencias','password'=>'Contraseña'] : [];
if (is_admin()) $nav += ['rooms'=>'Salas','supplies'=>'Insumos','users'=>'Usuarios','loans'=>'Préstamos','reports'=>'Reportes'];
