<img src="assets/img/reservas.png" alt=""></span><span class="summary-label">Reservas activas hoy</span><strong><?=e((string)$summary['active_reservations'])?></strong></a><a class="summary-card summary-card-maintenance" href="?page=supplies"><span class="summary-icon" aria-hidden="true"><img src="assets/img/equipo.png" alt=""></span><span class="summary-label">Equipos en mantenimiento</span><strong><?=e((string)$summary['maintenance'])?></strong></a><a class="summary-card summary-card-incidents" href="?page=incidents"><span class="summary-icon" aria-hidden="true"><img src="assets/img/incidencia.png" alt=""></span><span class="summary-label">Incidencias abiertas</span><strong><?=e((string)$summary['open_incidents'])?></strong></a></div></aside></div><?php elseif ($page === 'availability'): $availabilityInput=['resource'=>(string)($_GET['resource']??''),'reservation_date'=>(string)($_GET['reservation_date']??date('Y-m-d')),'start_time'=>(string)($_GET['start_time']??'09:00'),'end_time'=>(string)($_GET['end_time']??'10:00'),'quantity'=>(string)($_GET['quantity']??'1')]; $availabilityResult=null; $availabilityError=null; if(isset($_GET['check'])){try{[$availabilityType,$availabilityId]=Input::resource($availabilityInput['resource']);$availabilityResult=$app->checkAvailability(['resource_type'=>$availabilityType,'resource_id'=>$availabilityId,'reservation_date'=>$availabilityInput['reservation_date'],'start_time'=>$availabilityInput['start_time'],'end_time'=>$availabilityInput['end_time'],'quantity'=>$availabilityInput['quantity']]);}catch(Throwable $error){if(!($error instanceof InvalidArgumentException))log_internal_error($error);$availabilityError=user_error_message($error);}} ?>
